class Solution:
    def stringSequence(self, target: str) -> List[str]:
        res = []; cur = ''
        for ch in target:
            cur += 'a'; res.append(cur)
            while cur[-1] != ch:
                cur = cur[:-1] + chr(ord(cur[-1]) + 1)
                res.append(cur)
        return res

