class Solution {
public:
    vector<string> stringSequence(string target) {
        vector<string> res; string cur;
        for (char ch : target) {
            cur += 'a'; res.push_back(cur);
            while (cur.back() != ch) { cur.back()++; res.push_back(cur); }
        }
        return res;
    }
};

c.java:
class Solution {
    public List<String> stringSequence(String target) {
        List<String> res = new ArrayList<>(); StringBuilder cur = new StringBuilder();
        for (char ch : target.toCharArray()) {
            cur.append('a'); res.add(cur.toString());
            while (cur.charAt(cur.length() - 1) != ch) {
                cur.setCharAt(cur.length() - 1, (char)(cur.charAt(cur.length() - 1) + 1));
                res.add(cur.toString());
            }
        }
        return res;
    }
}

