    const res = []; let cur = '';
    for (const ch of target) {
        cur += 'a'; res.push(cur);
        while (cur[cur.length - 1] !== ch) {
            cur = cur.slice(0, -1) + String.fromCharCode(cur.charCodeAt(cur.length - 1) + 1);
            res.push(cur);
        }
    }
    return res;
};

